# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# check_growth_output ----
## Setup ----
# von Bertalanffy growth with the setup_default_Growth() values, here at
# reference ages 4 and 18 of ages 0 to 20, and weight-at-age data for 30
# years and the year after.
ages <- 0:20
n_years <- 30
vonb_growth <- FIMS:::von_bertalanffy_schnute_growth(
  age = ages,
  log_growth_coefficient = log(0.18),
  log_length_weight_a = log(2.5e-11),
  log_length_weight_b = log(3),
  reference_ages = c(4, 18),
  length_edges = seq(0, 1500, 10),
  log_difference_mean_length_old = log(725 - 275),
  log_mean_length_young = log(275),
  log_length_at_age_sd_young = log(28),
  log_length_at_age_sd_old = log(73)
)
ewaa_growth <- FIMS:::ewaa_growth(
  weight_at_age = matrix(1, n_years + 1, length(ages))
)
check <- function(growth, module_type = "VonBertalanffySchnute") {
  FIMS:::check_growth_output(growth, module_type, length(ages), n_years)
}

## IO correctness ----
test_that("`check_growth_output()` works with correct inputs", {
  #' @description Test that `check_growth_output()` accepts every output of von Bertalanffy growth.
  expect_true(check(vonb_growth))
  #' @description Test that `check_growth_output()` accepts EWAA weight at age with 1 row per year plus the year after the last model year.
  expect_true(check(ewaa_growth, "EWAA"))
})

## Edge handling ----
test_that("`check_growth_output()` returns correct outputs for edge cases", {
  #' @description Test that `check_growth_output()` accepts weight at age as 1 value per age, the same in every year.
  expect_true(check(list(weight_at_age = rep(1, length(ages))), "EWAA"))
  #' @description Test that `check_growth_output()` accepts von Bertalanffy growth without length bins, which has no length_probability.
  expect_true(check(vonb_growth[c(
    "weight_at_age", "mean_length_at_age", "sd_length_at_age"
  )]))
})

## Error handling ----
test_that("`check_growth_output()` returns correct error messages", {
  mean_length <- vonb_growth[["mean_length_at_age"]]
  short_mean_length <- vonb_growth
  short_mean_length[["mean_length_at_age"]] <- mean_length[-1]
  #' @description Test that `check_growth_output()` stops when mean length at age has 1 value fewer than the ages.
  expect_error(
    object = check(short_mean_length),
    regexp = "mean_length_at_age.*of size 20"
  )
  #' @description Test that `check_growth_output()` stops when weight at age by year has no row for the year after the last model year.
  expect_error(
    object = check(
      list(weight_at_age = matrix(1, n_years, length(ages))),
      "EWAA"
    ),
    regexp = "of size 30 x 21.*needs size 31 x 21"
  )
  length_probability <- vonb_growth[["length_probability"]]
  wrong_rows <- vonb_growth
  wrong_rows[["length_probability"]] <- length_probability[-1, ]
  #' @description Test that `check_growth_output()` stops when P(length | age) does not have 1 row per age.
  expect_error(
    object = check(wrong_rows),
    regexp = "length_probability.*of size 20 x 150"
  )
  two_values <- vonb_growth
  two_values[["length_weight_a"]] <- rep(vonb_growth[["length_weight_a"]], 2)
  #' @description Test that `check_growth_output()` stops when the length-weight alpha has more than 1 value.
  expect_error(
    object = check(two_values),
    regexp = "length_weight_a.*of size 2"
  )
})

test_that("the catch-at-age model stops when growth returns an output of the wrong size", {
  # EWAA growth that returns weight at age for the first 6 of 12 ages only.
  # Without the check, the model recycles the 6 values with no error.
  short_ewaa <- FIMS:::growth_modules
  short_ewaa[["EWAA"]][["evaluate"]] <- function(weight_at_age) {
    list(weight_at_age = weight_at_age[1, 1:6])
  }
  local_mocked_bindings(growth_modules = short_ewaa)
  data_4_model <- FIMSFrame(data_big)
  #' @description Test that the catch-at-age model calls `check_growth_output()`, so a growth module that returns too few ages of weight at age stops it.
  expect_error(
    object = setup_default_parameters(data_4_model) |>
      initialize_fims(data = data_4_model) |>
      fit_fims(optimize = FALSE),
    regexp = "weight_at_age.*of size 6\\."
  )
})
